package dev.hrutvik.filesync.upload;
import dev.hrutvik.filesync.blob.MultipartBlobGateway; import dev.hrutvik.filesync.version.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service public class UploadSessionService {
 private final UploadSessionStore store; private final MultipartBlobGateway blobs; private final Duration lifetime;
 public UploadSessionService(UploadSessionStore store,MultipartBlobGateway blobs,@Value("${filesync.upload.session-ttl:PT1H}") Duration lifetime){this.store=store;this.blobs=blobs;this.lifetime=lifetime;}
 public UploadSessionResponse create(String tenant,CreateUploadSessionRequest request){String hash=request.contentHash().toLowerCase(Locale.ROOT);String fp=FileVersionService.fingerprint(request.operationId(),hash,request.sizeBytes(),request.partCount());var existing=store.findByOperation(tenant,request.operationId());if(existing.isPresent()){if(!fp.equals(existing.get().fingerprint()))throw new VersionConflictException("operationId was already used with a different upload request");return response(existing.get(),true);}String key="blobs/"+hash.substring(0,2)+"/"+hash;var remote=blobs.initiate(key,hash);try{var session=store.insert(tenant,request.operationId(),fp,hash,request.sizeBytes(),request.partCount(),key,remote.uploadId(),Instant.now().plus(lifetime));return response(session,false);}catch(RuntimeException failure){blobs.abort(key,remote.uploadId());throw failure;}}
 @Transactional public UploadSessionResponse complete(String tenant,UUID id,CompleteUploadSessionRequest request){var session=store.lock(id,tenant).orElseThrow(()->new IllegalArgumentException("upload session not found"));if("COMPLETED".equals(session.status()))return response(session,true);if(Instant.now().isAfter(session.expiresAt()))throw new IllegalStateException("upload session expired");validateParts(session.partCount(),request);var parts=request.parts().stream().map(p->new MultipartBlobGateway.CompletedUploadPart(p.partNumber(),p.eTag())).toList();blobs.complete(session.objectKey(),session.remoteUploadId(),parts);var head=blobs.head(session.objectKey());if(head.sizeBytes()!=session.sizeBytes()||!session.hash().equals(head.declaredHash()))throw new IllegalStateException("completed blob does not match the declared size and hash metadata");store.markCompleted(id);return response(new UploadSessionStore.Session(session.id(),session.operationId(),session.fingerprint(),session.hash(),session.sizeBytes(),session.partCount(),session.objectKey(),session.remoteUploadId(),"COMPLETED",session.expiresAt()),false);}
 private UploadSessionResponse response(UploadSessionStore.Session s,boolean replayed){var parts="READY".equals(s.status())?blobs.presign(s.objectKey(),s.remoteUploadId(),s.partCount()):List.<MultipartBlobGateway.PartUpload>of();return new UploadSessionResponse(s.id(),s.hash(),s.sizeBytes(),s.partCount(),s.status(),s.expiresAt(),parts,replayed);}
 static void validateParts(int expected,CompleteUploadSessionRequest r){if(r.parts().size()!=expected)throw new IllegalArgumentException("every part must be supplied exactly once");var seen=new HashSet<Integer>();for(var p:r.parts())if(p.partNumber()>expected||!seen.add(p.partNumber()))throw new IllegalArgumentException("part numbers must be unique and within the session range");}
}
